import React, { Component } from 'react'
import { FormWrapper } from './career.style'
import { imageUrls } from './content'
import { Input, Form, Button, Upload, Spin, notification, Row, Col } from 'antd'
import careerActions from '../../../redux/career/actions'
import { connect } from 'react-redux'
import ThankYouComponent from './thankyou'
import AppFooter from '../../../components/Footer/footer'

const { uploadDocuments, resetDataCareer, applyJob } = careerActions

function hasErrors (fieldsError) {
  return Object.keys(fieldsError).some(field => fieldsError[field])
}
const { TextArea } = Input
const FormItem = Form.Item

class FormSubmit extends Component {
  constructor (props) {
    super(props)
    this.state = {
      uuid: '',
      formDataUpload: [],
      uploadedMessage: '',
      fileName: '',
      fileType: '',
      selectedJob: {},
      formState: 0
    }
  }

  componentWillMount = () => {
    const { action, location } = this.props.history
    const { state } = location
    if (action === 'PUSH') {
      this.setState({
        selectedJob: state
      })
    } else {
      this.props.history.push('/career')
    }
  };

  componentWillReceiveProps (nextProps) {
    console.log('nextprops', nextProps)

    const { uploadData, applyFormStatus, uploadMessage } = nextProps
    if (applyFormStatus === 'error' || uploadMessage === 'error') {
      this.setState({
        uploadedMessage: ''
      }, () => {
        this.props.resetDataCareer()
      })
    }
    if (uploadMessage === 'success') {
      uploadData['uid'] = this.state.uuid
      this.setState({
        uploadedMessage: '',
        formDataUpload: [...this.state.formDataUpload, uploadData]
      }, () => {
        this.props.resetDataCareer(['uploadMessage'])
      })
    }
    if (applyFormStatus === 'success') {
      this.setState(
        {
          formState: 1
        }, () => {
          window.scrollTo(0, 0)
          this.props.resetDataCareer(['applyFormStatus'])
        })
    }
  }

  customRequest = ({ onSuccess, onError, file }) => {
    const { fileName, fileType } = this.state
    const { size, type, name, uid } = file
    this.setState({
      uuid: uid,
      uploadedMessage: 'loading'
    })

    const isLt10KB = size / 1024 / 1024 < 0.01
    const isGt5000KB = size / 1024 / 1024 > 5

    if (isLt10KB) {
      notification['error']({
        message: 'Ukuran file minimal 10KB'
      })
    }

    if (isGt5000KB) {
      notification['error']({
        message: 'Ukuran file maksimal 5MB'
      })
    }

    const allowedExtensions = [
      'application/pdf',
      'application/msword',
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
    ]

    if (!allowedExtensions.includes(type) && !isLt10KB && !isGt5000KB) {
      this.setState({
        uuid: '',
        uploadedMessage: ''
      })
      notification['error']({
        message: 'Mohon gunakan PDF/Doc'
      })
    }
    this.setState({
      fileType: [...fileType, type],
      fileName: [...fileName, name],
      disableSendModal: true
    })
    // TODO: move this to check using props field value instead of having to store to state

    try {
      let formData = new FormData()
      formData.append('file', file)
      this.props.uploadDocuments(formData)
    } catch (error) {
      this.setState({ disableSendModal: false })
      notification['error']({
        message: 'Error while uploading!'
      })
    }
  };

  removeFile = file => {
    const { formDataUpload } = this.state
    var filterImage = formDataUpload.filter(item => item.status === 'done')
    this.setState(
      {
        formDataUpload: filterImage
      },
      () => {
        this.props.resetDataCareer()
      }
    )
  };

  handleSubmitLeft = e => {
    e.preventDefault()
    const { formDataUpload, selectedJob } = this.state
    let applyingFormData = []

    if (formDataUpload.length) {
      formDataUpload.map(item => {
        if (Object.keys(item).length > 0) {
          applyingFormData.push({
            filename: item.name,
            url: item.url
          })
        }
      })
      this.props.form.validateFields((err, values) => {
        if (!err) {
          values['job_title'] = selectedJob.position
          values['job_type'] = selectedJob.jobSpan
          values['job_location'] = selectedJob.jobLocation
          values['docs'] = applyingFormData
          this.props.applyJob(values)
        }
      })
    } else {
      alert('No Files Attached')
    }
  };

  render () {
    const {
      getFieldDecorator,
      getFieldsError
    } = this.props.form
    const {
      selectedJob,
      formState,
      formDataUpload,
      uploadedMessage
    } = this.state
    switch (formState) {
      case 0: return (
        <div>
          <FormWrapper>
            <div className='flex-container paddingTB20LR50 bg-white head-section'>
              <div className='heading text-yellow paddingLR20'>
                {selectedJob.position}
              </div>
              <div className='job-description-tags paddingLR20'>
                <div id='photo' className='technology-tag'>
                  <img className='tag-image' src={imageUrls.portfolio} />
                  <span className='tag-name'>&nbsp;&nbsp;Technology</span>
                </div>
                <div id='photo' className='technology-tag marginLeft'>
                  <img className='tag-image' src={imageUrls.jobTime} />
                  <span className='tag-name'>&nbsp;&nbsp;Full Time</span>
                </div>
                <div id='photo' className='technology-tag marginLeft'>
                  <img className='tag-image' src={imageUrls.placeTag} />
                  <span className='tag-name'>&nbsp;&nbsp;Indonesia</span>
                </div>
              </div>
            </div>
            <Form onSubmit={this.handleSubmitLeft}>
              <div className='paddingTB20LR50 bg-gray'>
                <div className='bg-white padding20'>
                  <h3 className='text-yellow marginB-45'>
                    Submit Your Application
                  </h3>
                  <Row type='flex' align='middle' className='marginB-20'>
                    <Col xl={8} lg={8} md={8} sm={12} xs={24}>
                      <p className='paddingTB10'>Portfolio URL</p>
                    </Col>
                    <Col xl={4} lg={4} md={4} sm={4} xs={24}>
                      <FormItem>
                        {getFieldDecorator('website_reference')(
                          <Input
                            className='custom-input'
                            prefix={<img src={imageUrls.globe} />}
                            placeholder='PortFolio'
                          />
                        )}
                      </FormItem>
                    </Col>
                  </Row>
                  <Row type='flex' align='middle' className='marginB-45'>
                    <Col xl={8} lg={8} md={8} sm={12} xs={24} gutter={20}>
                      <p className='paddingTB10'>
                        Resume/CV <span className='astrik'>✱</span>
                      </p>
                    </Col>

                    <Col xl={4} lg={4} md={4} sm={4} xs={20}>
                      <Spin spinning={uploadedMessage !== ''}>
                        <Upload
                          customRequest={file => this.customRequest(file)}
                          onRemove={file => this.removeFile(file)}
                          fileList={
                            formDataUpload.length
                              ? formDataUpload.filter(
                                item => item.status === 'done'
                              )
                              : []
                          }
                        >
                          <Button
                            size='large'
                            className='searchButton'
                            type='primary'
                          >
                            Upload
                          </Button>
                        </Upload>
                      </Spin>
                    </Col>
                  </Row>
                  <h3 className='text-yellow marginB-45'>Personal Info</h3>
                  <Row type='flex' align='middle' className='marginB-20'>
                    <Col xl={8} lg={8} md={8} sm={12} xs={24}>
                      <p className='paddingTB10'>
                        Full name <span className='astrik'>✱</span>
                      </p>
                    </Col>

                    <Col xl={16} lg={16} md={16} sm={12} xs={24}>
                      <FormItem>
                        {getFieldDecorator('name', {
                          rules: [
                            {
                              required: true,
                              message: 'Name required',
                              whitespace: true
                            }
                          ]
                        })(
                          <Input
                            className='custom-input'
                            prefix={<img src={imageUrls.user} />}
                            placeholder='Nama'
                          />
                        )}
                      </FormItem>
                    </Col>
                  </Row>
                  <Row type='flex' align='middle' className='marginB-20'>
                    <Col xl={8} lg={8} md={8} sm={12} xs={24}>
                      <p className='paddingTB10'>
                        Email <span className='astrik'>✱</span>
                      </p>
                    </Col>

                    <Col xl={16} lg={16} md={16} sm={12} xs={24}>
                      <FormItem>
                        {getFieldDecorator('email', {
                          rules: [
                            {
                              type: 'email',
                              message: 'The input is not valid E-mail!'
                            },
                            {
                              required: true,
                              message: 'Please input your E-mail!'
                            }
                          ]
                        })(
                          <Input
                            className='custom-input'
                            prefix={<img src={imageUrls.email} />}
                            placeholder='Email'
                          />
                        )}
                      </FormItem>
                    </Col>
                  </Row>
                  <Row type='flex' align='middle' className='marginB-45'>
                    <Col xl={8} lg={8} md={8} sm={12} xs={24}>
                      <p className='paddingTB10'>
                        Phone <span className='astrik'>✱</span>
                      </p>
                    </Col>

                    <Col xl={16} lg={16} md={16} sm={12} xs={24}>
                      <FormItem>
                        {getFieldDecorator('phone', {
                          rules: [
                            {
                              required: true,
                              message: 'Please input your phone Number!'
                            }
                          ]
                        })(
                          <Input
                            className='custom-input'
                            prefix={<img src={imageUrls.phone} />}
                            placeholder='Phone'
                          />
                        )}
                      </FormItem>
                    </Col>
                  </Row>
                  <h3 className='text-yellow marginB-45'>
                    Additional Information
                  </h3>
                  <Row type='flex' align='middle' className='marginB-20'>
                    <Col xl={24} lg={24} md={24} sm={24} xs={24}>
                      <FormItem>
                        {getFieldDecorator('additional_info')(
                          <TextArea className='custom-input' rows={6} />
                        )}
                      </FormItem>
                    </Col>
                  </Row>

                  <Row
                    type='flex'
                    align='middle'
                    justify='space-between'
                    className='marginB-20'
                  >
                    <Col span={24}>
                      <FormItem className='floatR display-inline'>
                        <Button
                          size='large'
                          className='button-apply btn display-inline'
                          type='primary'
                          htmlType='submit'
                          disabled={hasErrors(getFieldsError())}
                        >
                          Submit Application
                        </Button>
                      </FormItem>
                      <Button
                        size='large'
                        className='display-inline btn backButton'
                        type='primary'
                        onClick={() => this.props.history.goBack()}
                      >
                        Cancel
                      </Button>
                    </Col>
                  </Row>
                </div>
              </div>
            </Form>
          </FormWrapper>
          <AppFooter />
        </div>
      )
      case 1: return (
        <ThankYouComponent history={this.props.history} />
      )
      default: return ''
    }
  }
}
const WrappedForm = Form.create()(FormSubmit)
export default connect(
  state => ({
    applyFormStatus: state.Career.applyFormStatus,
    uploadData: state.Career.uploadData,
    uploadMessage: state.Career.uploadMessage
  }),
  {
    uploadDocuments,
    resetDataCareer,
    applyJob
  }
)(WrappedForm)
